"""Resource annotations: why to read + level. Rule-based by source type so no claim is invented
about a page's content beyond what its title and source type establish."""
from urllib.parse import urlparse
RULES=[  # (domain substring or path hint, kind, level, why template)
 ("arxiv.org","paper","advanced","The primary research paper behind this idea. Read the abstract, figures and method section to see where the technique comes from and what was actually measured."),
 ("crfm.stanford.edu","research","advanced","Research output from Stanford CRFM; useful for the original framing and evaluation methodology."),
 ("cs336.stanford.edu","course","advanced","University course material that builds the topic from scratch; best when you want depth and exercises."),
 ("web.stanford.edu","course","intermediate","University lecture material with a structured treatment of the topic."),
 ("deeplearningbook.org","book","advanced","Textbook-level treatment; use it as a rigorous reference for the underlying math."),
 ("d2l.ai","book","intermediate","Interactive textbook with runnable code; good for learning by doing."),
 ("3blue1brown","video","intro","Visual, intuition-first explanations; a gentle start before the math."),
 ("fullstackdeeplearning","course","intermediate","Practitioner course material focused on shipping ML systems."),
 ("huggingface.co/learn","course","intro","Free hands-on course chapters with code; good first practical exposure."),
 ("huggingface.co","docs","intermediate","Hugging Face documentation or guide with practical, code-level detail."),
 ("github.com","code","intermediate","Source repository: read the README and examples to see how it is used in practice."),
 ("github.io","docs","reference","Project documentation; the authoritative description of the spec or tool."),
 ("modelcontextprotocol.io","spec","reference","The official MCP specification and docs; the source of truth for protocol behavior."),
 ("nist.gov","standard","reference","Official NIST publication; the primary source for the framework's terms and requirements."),
 ("iso.org","standard","reference","Official ISO standard page; scope and structure of the standard (full text is paid)."),
 ("artificialintelligenceact.eu","regulation","reference","Browsable text and summaries of the EU AI Act; check dates against the Official Journal."),
 ("owasp.org","security","intermediate","OWASP community guidance listing risks and mitigations; good for threat modeling checklists."),
 ("atlas.mitre.org","security","reference","MITRE ATLAS knowledge base of adversary tactics and techniques against AI systems."),
 ("sre.google","book","intermediate","Google's SRE books, freely online; the canonical source for SLOs, error budgets and incident practice."),
 ("anthropic.com","guide","intermediate","Vendor engineering write-up or guide with practical patterns from building with LLMs."),
 ("openai.com","docs","intermediate","Vendor documentation or guide; precise API behavior and recommended practice."),
 ("docs.claude.com","docs","intermediate","Vendor documentation with exact API behavior and examples."),
 ("docs.anthropic.com","docs","intermediate","Vendor documentation with exact API behavior and examples."),
 ("nvidia","docs","advanced","NVIDIA technical documentation; precise details on hardware, libraries and performance tuning."),
 ("vllm","docs","intermediate","vLLM documentation or blog; how a leading open-source inference engine implements this."),
 ("sglang","docs","intermediate","SGLang documentation; another major inference engine's approach and configuration."),
 ("litellm","docs","intermediate","LiteLLM gateway documentation; concrete configuration for routing, budgets and fallbacks."),
 ("opentelemetry.io","spec","reference","OpenTelemetry documentation and semantic conventions; the vendor-neutral standard for traces."),
 ("finops.org","framework","intermediate","FinOps Foundation guidance; shared vocabulary and practices for cloud cost management."),
 ("learn.microsoft.com","docs","intermediate","Microsoft Learn documentation with step-by-step guidance and architecture notes."),
 ("aws.amazon.com","docs","intermediate","AWS documentation; exact service behavior, limits and configuration."),
 ("cloud.google.com","docs","intermediate","Google Cloud documentation or architecture guide."),
 ("kubernetes.io","docs","intermediate","Official Kubernetes documentation; the reference for the concepts used here."),
 ("k8s.io","docs","advanced","Kubernetes SIG project documentation for specialized scheduling and batch workloads."),
 ("docker.com","docs","intro","Official Docker documentation; clear introductions with commands to try."),
 ("pytorch.org","docs","intermediate","Official PyTorch documentation or tutorial with runnable code."),
 ("ray.io","docs","intermediate","Ray documentation; distributed compute patterns with examples."),
 ("oreilly.com","book","intermediate","Practitioner book; broad, well-edited coverage from experienced engineers."),
 ("infoq.com","talk","intermediate","Conference talk or article with real-world experience reports."),
 ("simonwillison.net","blog","intermediate","Widely cited practitioner blog with clear explanations of LLM security issues."),
 ("hamel.dev","blog","intermediate","Practitioner write-up on evals and error analysis with concrete workflows."),
 ("ragas","docs","intermediate","RAG evaluation library documentation; metric definitions you can run."),
 ("getdbt.com","docs","intro","dbt documentation; approachable guides to modeling and testing data."),
 ("databricks.com","docs","intermediate","Databricks documentation or guide on platform features discussed here."),
 ("aisi.org.uk","docs","intermediate","UK AI Security Institute's Inspect framework docs for building evals."),
 ("developer.mozilla.org","docs","reference","MDN web docs; precise reference for web platform behavior."),
 ("12factor.net","guide","intro","Short classic guide to building deployable services."),
 ("teamtopologies.com","guide","intro","Concepts for organizing teams and platforms; light reading with strong ideas."),
 ("ml-ops.org","guide","intro","Community overview of MLOps principles and lifecycle."),
]
def note(url,title,subject):
    host=urlparse(url).netloc+urlparse(url).path
    for key,kind,level,why in RULES:
        if key in host: return {"kind":kind,"level":level,"why":why}
    return {"kind":"guide","level":"intermediate","why":f"An external guide on {title} that complements the {subject} lesson with another author's explanation and examples."}
